SELECT COUNT(DISTINCT cs.student_id)
FROM class_students cs
WHERE cs.class_id IN (
    SELECT cc.id FROM course_classes cc WHERE cc.course_id = #{courseId}
    UNION
    SELECT cc_c.class_id FROM class_courses cc_c WHERE cc_c.course_id = #{courseId}
)

SELECT IFNULL(SUM(expected_count - submitted_count), 0) AS missing_count FROM ( SELECT a.id AS assignment_id, COUNT(DISTINCT cs.student_id) AS expected_count, COUNT(DISTINCT s.student_id) AS submitted_count FROM assignments a JOIN ( SELECT cc.id AS class_id, cc.course_id FROM course_classes cc UNION SELECT cc_c.class_id, cc_c.course_id FROM class_courses cc_c ) AS all_classes ON a.course_id = all_classes.course_id JOIN class_students cs ON all_classes.class_id = cs.class_id LEFT JOIN assignment_submissions s ON s.assignment_id = a.id AND s.student_id = cs.student_id WHERE a.teacher_id = #{teacherId}
AND a.course_id = #{courseId}
AND all_classes.class_id = #{classId}
GROUP BY a.id ) t

SELECT COUNT(DISTINCT cs.student_id)
FROM assignments a
LEFT JOIN assignment_classes ac ON ac.assignment_id = a.id
LEFT JOIN class_students cs ON cs.class_id = ac.class_id
WHERE a.teacher_id = #{teacherId}
AND a.course_id = #{courseId}
AND ac.class_id = #{classId}

SELECT IFNULL(SUM(expected_students), 0) FROM (
    SELECT a.id AS assignment_id, COUNT(DISTINCT cs.student_id) AS expected_students
    FROM assignments a
    LEFT JOIN assignment_classes ac ON ac.assignment_id = a.id
    LEFT JOIN class_students cs ON cs.class_id = ac.class_id
    WHERE a.teacher_id = #{teacherId}
    AND a.course_id = #{courseId}
    AND ac.class_id = #{classId}
    GROUP BY a.id
) t

mapper.insert:
INSERT INTO assignment_classes (assignment_id, class_id)
SELECT DISTINCT #{assignmentId}, class_id FROM (
    SELECT cc.id AS class_id FROM course_classes cc
    WHERE cc.course_id = #{courseId} AND cc.teacher_id = #{teacherId}
    UNION
    SELECT cc_c.class_id AS class_id FROM class_courses cc_c
    WHERE cc_c.course_id = #{courseId} AND cc_c.teacher_id = #{teacherId}
) AS all_classes
